CommonData.BannerCustomCSS:
@import url('https://fonts.googleapis.com/css2?family=Overpass&display=swap');
/* Fuente */
 #onetrust-banner-sdk, #onetrust-policy-text, #onetrust-accept-btn-handler, #onetrust-reject-all-handler, #onetrust-pc-btn-handler {
     font-family: 'Overpass', sans-serif !important;
     font-size: 16px !important;
}

/*Título*/
#onetrust-policy-title {
     font-size: 24px !important;
     font-weight: 600 !important
     color: #37474F !important;
}

#onetrust-consent-sdk #onetrust-policy-title {
     color: #37474F !important;
}

/* Banner general */
 #onetrust-banner-sdk {
     overflow: hidden;
     position: fixed !important;
     bottom: 0px !important;
     left: 50% !important;
     transform: translateX(-50%) !important;
     min-width: 100% !important;
}

#onetrust-banner-sdk .ot-sdk-container {
  width: 98% !important;
  margin: 0 auto !important;
  text-align: center !important;
}

/* Desktop */
@media (min-width: 1024px) {
  #onetrust-banner-sdk .ot-sdk-container {
    width: 68% !important;
  }
}

@media (max-width: 768px){
#onetrust-banner-sdk #onetrust-button-group.ot-button-order-container{
    display: flex;
    flex-wrap: wrap;
    justify-content: flex-end;
    flex-direction: column-reverse;
}
}



/* Botones */
 #onetrust-accept-btn-handler, #onetrust-reject-all-handler{
     border-radius: 22px !important;
     border: 2px solid !important;
     min-width: 20% !important;
}
/* Botón Aceptar */
 #onetrust-accept-btn-handler {
     border: 2px solid #28892B !important;
     padding: 6px 24px 6px 24px;
}
/* Botón Rechazar */
 #onetrust-reject-all-handler {
     background-color: white !important;
     color: #37474F !important;
     min-width: 15% !important;
     padding: 6px 24px 6px 24px;
}

/*Boton configurar*/
#onetrust-pc-btn-handler {
    text-decoration: none !important;
}

#onetrust-banner-sdk #onetrust-accept-btn-handler, #onetrust-banner-sdk #onetrust-reject-all-handler, #onetrust-banner-sdk #onetrust-pc-btn-handler {
     padding: 6px 24px !important;
}

.onetrust-pc-dark-filter {
    background: rgb(255 255 255 / 50%);
}

#onetrust-policy-text a {
    text-decoration: none !important;
    font-weight: normal !important;
}

#onetrust-banner-sdk:focus,
#onetrust-banner-sdk *:focus {
  outline: none !important;
}

